#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum NumpyObject {
    Int(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    /// Each (re, im) represents a complex number.
    ComplexPairArray(Vec<(f64, f64)>),
    Str(String),
    Bool(bool),
    /// Generic object without inherent type information.
    Generic,
}

/// Map an object representation to a NumPy-like scalar type.
/// The `default` is used only if `rep` is `Generic`.
pub fn obj2sctype(
    rep: NumpyObject,
    default: Option<NumpyScalarType>,
) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Int(_) => Some(NumpyScalarType::Int64),
        NumpyObject::Float(_) => Some(NumpyScalarType::Float64),
        NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        NumpyObject::ComplexPairArray(_) => Some(NumpyScalarType::Complex128),
        NumpyObject::Str(_) => Some(NumpyScalarType::String),
        NumpyObject::Bool(_) => Some(NumpyScalarType::Bool),
        NumpyObject::Generic => default,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn typed_variants_ignore_default() {
        assert_eq!(
            obj2sctype(NumpyObject::Int(1), Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Str("x".into()), None),
            Some(NumpyScalarType::String)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Bool(true), Some(NumpyScalarType::Int64)),
            Some(NumpyScalarType::Bool)
        );
    }

    #[test]
    fn array_variants_map_to_element_dtype() {
        assert_eq!(
            obj2sctype(NumpyObject::IntArray(vec![1, 2]), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::FloatArray(vec![1.0, 2.0]), None),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::ComplexPairArray(vec![(0.0, 1.0)]), None),
            Some(NumpyScalarType::Complex128)
        );
    }

    #[test]
    fn generic_uses_default_or_none() {
        assert_eq!(
            obj2sctype(NumpyObject::Generic, Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(obj2sctype(NumpyObject::Generic, None), None);
    }
}